using MySqlConnector;
using OnlineElectronicSellingSystem.Data;
using OnlineElectronicSellingSystem.Models;

namespace OnlineElectronicSellingSystem.Repositories;

public sealed class SupportRepository
{
    private readonly Database database;
    public SupportRepository(Database database)=>this.database=database;
    public IReadOnlyList<SupportTicketRecord> Tickets(){using var c=database.OpenConnection();using var cmd=new MySqlCommand(@"SELECT t.id,t.user_id,u.full_name,au.full_name AS assigned_name,o.order_number,t.subject,t.category,t.status,t.created_at FROM support_tickets t JOIN users u ON u.id=t.user_id LEFT JOIN users au ON au.id=t.assigned_to LEFT JOIN orders o ON o.id=t.related_order_id ORDER BY t.created_at DESC",c);using var r=cmd.ExecuteReader();var a=new List<SupportTicketRecord>();while(r.Read())a.Add(new SupportTicketRecord{Id=r.GetInt32("id"),UserId=r.GetInt32("user_id"),CustomerName=r.GetString("full_name"),AssignedAgent=r.IsDBNull(r.GetOrdinal("assigned_name"))?null:r.GetString("assigned_name"),OrderNumber=r.IsDBNull(r.GetOrdinal("order_number"))?null:r.GetString("order_number"),Subject=r.GetString("subject"),Category=r.GetString("category"),Status=r.GetString("status"),CreatedAt=r.GetDateTime("created_at")});return a;}
    public IReadOnlyList<TicketMessageRecord> Messages(int ticketId){using var c=database.OpenConnection();using var cmd=new MySqlCommand("SELECT m.id,m.ticket_id,u.full_name,m.message,m.created_at FROM ticket_messages m JOIN users u ON u.id=m.user_id WHERE m.ticket_id=@ticket ORDER BY m.created_at",c);cmd.Parameters.AddWithValue("@ticket",ticketId);using var r=cmd.ExecuteReader();var a=new List<TicketMessageRecord>();while(r.Read())a.Add(new TicketMessageRecord{Id=r.GetInt32("id"),TicketId=r.GetInt32("ticket_id"),UserName=r.GetString("full_name"),Message=r.GetString("message"),CreatedAt=r.GetDateTime("created_at")});return a;}
    public void AddMessage(int ticketId,int userId,string message){using var c=database.OpenConnection();using var cmd=new MySqlCommand("INSERT INTO ticket_messages(ticket_id,user_id,message) VALUES(@ticket,@user,@message)",c);cmd.Parameters.AddWithValue("@ticket",ticketId);cmd.Parameters.AddWithValue("@user",userId);cmd.Parameters.AddWithValue("@message",message.Trim());cmd.ExecuteNonQuery();}
    public void UpdateTicket(int id,string status){using var c=database.OpenConnection();using var cmd=new MySqlCommand("UPDATE support_tickets SET status=@status,closed_at=IF(@status='Closed',CURRENT_TIMESTAMP,NULL) WHERE id=@id",c);cmd.Parameters.AddWithValue("@status",status);cmd.Parameters.AddWithValue("@id",id);cmd.ExecuteNonQuery();}
    public IReadOnlyList<NotificationRecord> Notifications(int userId){using var c=database.OpenConnection();using var cmd=new MySqlCommand("SELECT id,user_id,channel,notification_type,subject,message,delivery_status,created_at FROM notifications WHERE user_id IS NULL OR user_id=@user ORDER BY created_at DESC",c);cmd.Parameters.AddWithValue("@user",userId);using var r=cmd.ExecuteReader();var a=new List<NotificationRecord>();while(r.Read())a.Add(new NotificationRecord{Id=r.GetInt32("id"),UserId=r.IsDBNull(r.GetOrdinal("user_id"))?null:r.GetInt32("user_id"),Channel=r.GetString("channel"),NotificationType=r.GetString("notification_type"),Subject=r.IsDBNull(r.GetOrdinal("subject"))?null:r.GetString("subject"),Message=r.GetString("message"),DeliveryStatus=r.GetString("delivery_status"),CreatedAt=r.GetDateTime("created_at")});return a;}
    public void MarkNotification(int id,int userId){using var c=database.OpenConnection();using var cmd=new MySqlCommand("UPDATE notifications SET delivery_status='Read' WHERE id=@id AND (user_id IS NULL OR user_id=@user)",c);cmd.Parameters.AddWithValue("@id",id);cmd.Parameters.AddWithValue("@user",userId);cmd.ExecuteNonQuery();}
}
